<script setup lang="ts">
import type { ProductInput, VariantInput } from '~/services/moderator.api'
import { moderatorApi } from '~/services/moderator.api'
import { catalogApi } from '~/services/catalog.api'
import type { Category, Color, Size, Technique } from '~/types/catalog'
definePageMeta({ layout: 'moderator', middleware: 'moderator' })
const { data: metadata, error: metadataError } = await useAsyncData<{ getCategories: Category[]; getTechniques: Technique[]; getSizes: Size[]; getColors: Color[] }>('editor-metadata', () => catalogApi.metadata())
const form = reactive<ProductInput>({ name: '', slug: '', description: '', story: '', price: 0, discountPercentage: 0, categoryId: '', techniqueId: '', returnable: true })
const variants = ref<VariantInput[]>([]); const images = ref([{ url: '', alt: '' }]); const error = ref(''); const saving = ref(false)
watch(metadata, (data) => { if (!data) return; form.categoryId ||= data.getCategories[0]?.id ?? ''; form.techniqueId ||= data.getTechniques[0]?.id ?? ''; if (!variants.value.length && data.getSizes[0] && data.getColors[0]) variants.value.push({ sizeId: data.getSizes[0].id, colorId: data.getColors[0].id, sku: '', stock: 0, active: true }) }, { immediate: true })
function slugify() { if (!form.slug) form.slug = form.name.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') }
function addVariant() { const data = metadata.value; if (data?.getSizes[0] && data.getColors[0]) variants.value.push({ sizeId: data.getSizes[0].id, colorId: data.getColors[0].id, sku: '', stock: 0, active: true }) }
async function submit() { error.value = ''; saving.value = true; try { const product = (await moderatorApi.create({ ...form }, variants.value)).createProduct; for (const [position, image] of images.value.entries()) if (image.url && image.alt) await moderatorApi.addImage(product.id, image.url, image.alt, position); await navigateTo(`/moderator/products/${product.id}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to create product.' } finally { saving.value = false } }
</script>
<template><div><p class="text-xs font-bold uppercase tracking-widest text-slate-500">Catalogue control</p><h1 class="mt-2 font-display text-4xl">Create product</h1><p v-if="metadataError || error" class="mt-6 rounded-lg bg-rose-50 p-4 text-rose-800">{{ error || 'Unable to load catalogue options.' }}</p><form v-else class="mt-8 space-y-7" @submit.prevent="submit"><section class="card p-6"><h2 class="font-display text-2xl">Product details</h2><div class="mt-5 grid gap-4 md:grid-cols-2"><label class="label">Name<input v-model="form.name" class="field mt-1" required @blur="slugify"></label><label class="label">Slug<input v-model="form.slug" class="field mt-1" required pattern="[a-z0-9]+(-[a-z0-9]+)*"></label><label class="label">Category<select v-model="form.categoryId" class="field mt-1" required><option v-for="item in metadata?.getCategories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="label">Technique<select v-model="form.techniqueId" class="field mt-1" required><option v-for="item in metadata?.getTechniques" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="label">Price (USD)<input v-model.number="form.price" class="field mt-1" type="number" min="0" step="0.01" required></label><label class="label">Discount (%)<input v-model.number="form.discountPercentage" class="field mt-1" type="number" min="0" max="100" required></label></div><label class="label mt-4">Description<textarea v-model="form.description" class="field mt-1 min-h-28" minlength="10" required/></label><label class="label mt-4">Story<textarea v-model="form.story" class="field mt-1 min-h-32" minlength="10" required/></label><label class="mt-4 flex items-center gap-2 text-sm font-semibold"><input v-model="form.returnable" type="checkbox"> Returnable product</label></section><section class="card p-6"><div class="flex items-center justify-between"><h2 class="font-display text-2xl">Variants & stock</h2><button type="button" class="button-outline" @click="addVariant">Add variant</button></div><div v-for="(variant, index) in variants" :key="index" class="mt-4 grid gap-3 border-t pt-4 md:grid-cols-5"><select v-model="variant.colorId" class="field" aria-label="Color"><option v-for="color in metadata?.getColors" :key="color.id" :value="color.id">{{ color.name }}</option></select><select v-model="variant.sizeId" class="field" aria-label="Size"><option v-for="size in metadata?.getSizes" :key="size.id" :value="size.id">{{ size.name }}</option></select><input v-model="variant.sku" class="field" placeholder="SKU" required><input v-model.number="variant.stock" class="field" type="number" min="0" placeholder="Stock" required><button type="button" class="text-sm font-bold text-rose-700" :disabled="variants.length === 1" @click="variants.splice(index, 1)">Remove</button></div></section><section class="card p-6"><div class="flex items-center justify-between"><h2 class="font-display text-2xl">Images</h2><button type="button" class="button-outline" @click="images.push({ url: '', alt: '' })">Add image</button></div><div v-for="(image, index) in images" :key="index" class="mt-4 grid gap-3 md:grid-cols-2"><input v-model="image.url" class="field" type="url" placeholder="https://… image URL"><input v-model="image.alt" class="field" placeholder="Accessible image description"></div><p class="mt-3 text-sm text-slate-500">Images are URL references. A storage provider can be connected without changing products.</p></section><button class="button-primary" :disabled="saving">{{ saving ? 'Creating…' : 'Create draft product' }}</button></form></div></template>
